    private func imageHash(_ image: UIImage) -> String? {
        guard let data = image.jpegData(compressionQuality: 0.5) else { return nil }
        let digest = SHA256.hash(data: data)
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    /// Returns true if this image was already added (and records the hash if new).
    private func isDuplicate(_ image: UIImage) -> Bool {
        guard let hash = imageHash(image) else { return false }
        if imageHashes.contains(hash) { return true }
        imageHashes.insert(hash)
        return false
    }

